export async function checkpoint(args) {
  const session = await runScenario(args);
  const record = {
    created_at: new Date().toISOString(),
    scenario: args.scenario,
    kv_fingerprint: session.kvFingerprint,
    steps: session.steps.map(s => ({id: s.id, summary: s.summary}))
  };
  await fs.writeFile(args.out, JSON.stringify(record) + '
', {flag: 'a'});
}
